-- GENERATED by `wfj generate` from data/gossip/gossip-83.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["8300a633d3e248f7"] = { "Sì, sì, tutto il materiale bellico dell'Orda e dell'Alleanza viene spedito a ⟦Silithus=Silitus⟧ e dovrebbe arrivare entro un giorno. Sai cosa succede allora, {class}? Ci sbrighiamo per poi aspettare. Speriamo che qualcuno stia raccogliendo i pezzi dello Scettro delle Sabbie Mutevoli, perché per aprire i cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧ bisogna percuoterlo contro il gong sull'Altare dello Scarabeo.", "." },
  ["830631a13f893833"] = { "Hai <sbuffo> aiutato Mangletooth più di quanto avrei mai sognato, {race}.\n\nGrazie.\n\nFinché resterò in prigionia qui, puoi portarmi i Frammenti di Sangue dei verrospini ⟦Bristleback=Mantotergo⟧ e ti benedirò con il potere di Agamaggan.", "." },
  ["830ae28b240810dc"] = { "Quindi sei qui per le asce dei ⟦Warsong=Cantaguerra⟧. Be', era ora, {name}. Quella cassa è lì fuori da giorni, ormai.\n\nPortala via pure quando sei <pronto/pronta>.", "." },
  ["830af2f1c8b5db16"] = { "Ehi, ragazzi, proviamo dall'altra parte.", "." },
  ["830e700033d39854"] = { "L'Arcidruido crede che Ivus, il Signore della Foresta, verrà non appena sarà informato delle forze distruttive in questa valle.", "." },
  ["831691608dc5a777"] = { "{name} ha lasciato cadere la Bandiera dell'⟦Alliance=Alleanza⟧!", "." },
  ["83236058efc4b2b2"] = { "L'arte degli elfi della notte va oltre i boschi e le creature che li abitano. Sappiamo molto della terra sotto di noi, e dei metalli che racchiude.", "." },
  ["832513f8e27d7e14"] = { "Sì, hai sentito bene, {class}: tutte le nostre raccolte sono complete e l'ultimo carico di materiale bellico dovrebbe arrivare a ⟦Silithus=Silitus⟧ entro un giorno. Mi dicono che, una volta radunato tutto lì e pronte le truppe, qualcuno tra le file di voi eroi suonerà il gong fuori da ⟦Ahn'Qiraj=Ahn'qiraj⟧, dopo aver ricomposto lo Scettro delle Sabbie Mutevoli per farlo. Spero che non si debba aspettare troppo.", "." },
  ["8325735e15ee5a47"] = { "%s raduna i materiali e si mette al lavoro.", "." },
  ["83262fde16f7d881"] = { "Esattamente.", "." },
  ["83264bfe12812a90"] = { "Il ⟦Icewing Bunker=Fortilizio di Algidala⟧ è stato conquistato dall'⟦Alliance=Alleanza⟧!", "." },
  ["832d16e9757e01ab"] = { "Alle mie spalle c'è l'Altare di Zanza, un luogo sacro per noi Zandalari. Qui preghiamo per rafforzare la nostra determinazione in vista della guerra contro il Dio del Sangue, Hakkar.\n\nDai prova di te alla tribù usando l'altare per distruggere tutti gli Hakkari Bijou che potresti trovare dentro ⟦Zul'Gurub=Zul'gurub⟧. Inoltre, ti darò gli Emblemi dell'Onore che usa la nostra tribù in cambio delle serie di monete che potresti trovare a ⟦Zul'Gurub=Zul'gurub⟧. Portami le monete che cerco, e sarai <ricompensato/ricompensata>!", "." },
  ["83332c1116c2c730"] = { "Non è ciò che Keever sperava. Keever forse ha messo troppa radice di terra. Vediamo se il secondo siero farà ciò che mi serve.", "." },
  ["8339d54371ceb04b"] = { "Torna indietro! Non svegliare il sognatore!", "." },
  ["83444f5b85c19633"] = { "Adele Fielder si è fatta un nome come conciatrice in tutta Elwynn. La trovi a lavorare in casa sua, vicino al ⟦Crystal Lake=Lago di Cristallo⟧.", "." },
  ["8345272677ad076b"] = { "Ascolto e ascolto, ma non sento questi spiriti di cui parla Karn.", "." },
  ["834643b0063eb8f6"] = { "Ahh, allora dovrai raggiungere la Hunter's Hall. Lì, sull'⟦Hunter Rise=Altura dei Cacciatori⟧, troverai diversi grandi cacciatori come Holt Thunderhorn.", "." },
  ["8348bf7b8f2b45cc"] = { "Ottimo lavoro! Meriti davvero il sapere che ti concederò!", "." },
  ["834b33ff398b1768"] = { "Hai imparato tutto ciò che posso insegnarti, {name}. Che le benedizioni della Madre Terra ti guidino nella scelta di un famiglio.\n\nEcco a te, {name}. Ora ti darò il potere di addomesticare una bestia, e di richiamarla e congedarla come meglio credi. Usa le tue nuove abilità con orgoglio e onora la Madre Terra.", "." },
  ["834dc587955cdac7"] = { "Io contro cinquanta orchi? Non ci casco, {name}. Il mio paparino diceva sempre: «La discrezione è la parte migliore del biscotto», o qualcosa del genere, e io sapevo cosa voleva dire.", "." },
  ["834e6c60b98c4d0d"] = { "Salve! Sei proprio la persona che cercavo. Siediti e ascolta, perché ho un piano che ci farà diventare ricchi tutti e due!", "." },
  ["8351f0c5f2951df9"] = { "Informazioni sulle Scaglie Cromatiche Brillanti.", "." },
  ["8356e966e9105596"] = { "Papà!", "." },
  ["8359f8c1f195e36a"] = { "Le ceneri dell'Uomo di Paglia in fiamme irradiano potere magico.", "." },
  ["835a2b1feeb5d63e"] = { "Ehi, chi è che Fengus chiama amico degli gnoll?! Porta i prigionieri dal re; hai fatto bene a portarli con le loro armi, così mostri al re che sono una minaccia. Io vado a vedere se Fengus fa ancora lo spaccone quando gli do una bella batosta! HAR!", "." },
  ["835cc67fbadb69dd"] = { "La morte della nostra carne ha segnato la nascita del nostro spirito e del nostro sacro compito.", "." },
  ["83630cf57b1accde"] = { "Tu va' all'anello interno dell'Apothecarium. Lavinia Crowe è lì.", "." },
  ["83637c7e14ac6bd2"] = { "La temperatura è di 122 gradi Kraklenheit.", "." },
  ["83707691162a564f"] = { "Morire in battaglia è glorioso! Ma con quello che ti insegno, forse tu non muori così presto, eh?", "." },
  ["8371c2f988529cd4"] = { "%s si rifiuta di morire mentre il suo padrone è in pericolo!", "." },
  ["8375d2c5083050bc"] = { "Proprio così, le colline di ⟦Winterspring=Fontefredda⟧ stanno cercando di resistere a un nuovo assalto del Flagello. Il tuo contributo le aiuterebbe molto.\n\nNecropoli rimanenti: $2284W", "." },
  ["837b51080daaf5cb"] = { "Puoi dirlo forte! È ancora più strano se pensi che tra Brann, Rutgar, me e la scimmia conosciamo 38 lingue diverse, compreso un pizzico di ⟦Titan=Titano⟧, sia vanir sia aesir.\n\nComunque, qualunque cosa stesse ticchettando, di sicuro non parlava con nessuno dei «presenti». Poi ha annuito ed è passata all'attacco! Ci ha aggrediti senza esitare!", "." },
  ["837d4c7785803cac"] = { "Nessun'altra razza di Azeroth ha sofferto quanto il nostro popolo, {class}. Ridere in faccia alla morte è diventato una seconda natura per tutti noi.", "." },
  ["83959312ba26ef73"] = { "Un altro sciocco cade nella trappola!", "." },
  ["839c020b966934f6"] = { "Il terreno su cui fu costruita la Scholomance fu donato a Kel'Thuzad dalla famiglia Barov. In cambio di questa terra, un luogo dove il Cult of the Damned potesse apprendere le magie immonde del Flagello, Kel'Thuzad concesse ai Barov l'immortalità attraverso la non morte.\n\nÈ nello Shadow Vault che troverai sia la Pelle dell'Ombra sia la sua proprietaria, lady Illucia Barov.\n\nNon è mai esistito specchio migliore per i vanitosi e per i morti.", "." },
  ["83b7b9da5d6d810e"] = { "%s percepisce la tua paura.", "." },
  ["83bf808ed9ac2f31"] = { "Bel colpo... ma non perfetto. Forse un po' più a sinistra.", "." },
  ["83c32533fd1131c2"] = { "Brontolio...", "." },
  ["83c9defa51d85432"] = { "Mio padre me l'aveva detto che sarebbero arrivati giorni come questo, in cui uno sconosciuto mi avrebbe parlato e avrei dovuto trattenermi dall'<ucciderlo/ucciderla>.", "." },
  ["83cae88f61b8c3d1"] = { "Mio padre me l'aveva detto che sarebbero arrivati giorni come questo, in cui uno sconosciuto mi avrebbe parlato e avrei dovuto trattenermi dall'<ucciderlo/ucciderla>.", "." },
  ["83cd1439021a1375"] = { "Ti parlerei, se avessi un odore migliore. Un po' di acqua di colonia non guasterebbe.", "." },
  ["83cdbdab9f53ac97"] = { "Bijou ha perso la strada! SQUAWK! *coff*", "." },
  ["83da33a9ab9a5f1c"] = { "E, eroi... io custodisco ciò che cercate. Che possa ancora una volta veder dissolversi il male. Remulos, fa' in modo che il nostro campione riceva il frammento dello Stormo Verde.", "." },
  ["83dcd2b371101e31"] = { "Sia lodata Elune... Eranikus è redento.", "." },
  ["83e46fb6657c03c9"] = { "Questo calderone ribolle di bolle verdi e dense. Teschi, ossa e organi di creature sconosciute nuotano nel suo brodo viscoso...\n\nE salgono pigramente in superficie i teschi di due troll un tempo possenti:\n\nGan'zulah e Nezzliok.", "." },
  ["83e92f2ecc06fe9a"] = { "No! Non devi farlo!", "." },
  ["83f969d22149b30b"] = { "Buongiorno, Hulfdan, cerco addestramento.", "." },
})
